<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {CompanyClient} from '$lib/utils/company-workspace';
 import {user} from '$lib/stores';
 export let companyId:string;
 export let people:any[]=[];export let bots:any[]=[];
 let client:CompanyClient,sessions:any[]=[],selected:any=null,rows:any[]=[],error='',direction='',busy=false,alive=true,reading=false;
 let timer:ReturnType<typeof setInterval>,pending='',writeId='';
 async function refresh(){if(reading||!alive)return;reading=true;try{const d=await client.request('/work-sessions');if(!alive)return;if(!Array.isArray(d.sessions)||d.sessions.some((s:any)=>s.companyId!==companyId))throw Error('Session company could not be verified.');sessions=d.sessions;if(selected){selected=sessions.find(s=>s.id===selected.id)||null;if(selected)await transcript();else{rows=[];direction='';}}error='';}catch(e){if(alive){sessions=[];selected=null;rows=[];direction='';error=(e as Error).message;}}finally{reading=false;}}
 async function transcript(){const id=selected.id,d=await client.request('/rooms/'+encodeURIComponent(id)+'/messages?limit=100');if(!alive||selected?.id!==id)return;if(d.messages.some((m:any)=>m.roomId!==id))throw Error('Transcript scope could not be verified.');rows=d.messages;}
 async function choose(s:any){selected=s;rows=[];direction='';pending='';try{await transcript();}catch(e){error=(e as Error).message;}}
 const allowed=(key:string)=>selected?.capabilities?.[key]===true&&selected.state!=='CLOSED';
 function person(id:string){return id===$user?.id?$user.name?.split(' ')[0]||'You':people.find(p=>p.id===id)?.name||'The administrator';}
 function speaker(m:any){return m.speaker.kind==='agent'?bots.find(b=>b.id===m.speaker.id)?.name||(!/^[a-f0-9-]{30,}$/i.test(m.speaker.id)?m.speaker.id:'AI agent'):person(m.speaker.id);}
 function state(s:any){return s.state==='HUMAN_FLOOR'?person(s.administratorId)+' is directing':s.state==='RUNNING'?'Bots are working':s.state==='CLOSED'?'Session ended':'Bot replies paused';}
 async function command(action:string,key:string){if(busy||!allowed(key))return;busy=true;const current=selected,id=current.id,body={action,expectedRevision:current.revision,content:action==='intervene'?direction:null},fingerprint=JSON.stringify([id,body]);if(pending!==fingerprint){pending=fingerprint;writeId=crypto.randomUUID();}
 try{await client.request('/work-sessions/'+encodeURIComponent(id)+'/commands','POST',body,writeId);if(alive&&selected?.id===id){pending='';if(action==='intervene')direction='';await refresh();}}catch(e){if(alive)error=(e as Error).message+' Direction remains unsent until confirmed.';}finally{if(alive)busy=false;}}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){alive=false;client.close();sessions=[];selected=null;rows=[];direction='';}}
 onMount(()=>{client=new CompanyClient(companyId,()=>localStorage.token||'',fetch,true);void refresh();timer=setInterval(()=>{if(!document.hidden)void refresh();},2000);window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{alive=false;client?.close();clearInterval(timer);});
</script>
<section class="work-sessions" aria-label="Recent bot-to-bot conversations"><header><h2>Recent bot-to-bot conversations</h2><button class="sd-button" on:click={refresh}>Refresh</button></header>
 <div class="session-list">{#each sessions as s(s.id)}<button class:selected={selected?.id===s.id} on:click={()=>choose(s)}><strong>{s.name}</strong><small>{s.visibility==='public'?'Company members':'Restricted audience'} · {state(s)}</small></button>{:else}<p>No visible work sessions.</p>{/each}</div>
 {#if selected}<div class="transcript"><p class="session-state">{state(selected)} <span>· {selected.visibility==='public'?'Company members':'Restricted audience'}</span></p>
 <div role="log" aria-label="Live speaker timeline">{#each rows as m(m.id)}<article class:human={m.intervention}><div class="speaker"><strong>{speaker(m)}{m.intervention?' · Human direction':m.speaker.kind==='agent'?' · AI agent':''}</strong><time>{new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div><p>{m.deleted?'Message deleted':m.content}</p></article>{/each}</div>
 {#if allowed('takeFloor')||allowed('pause')||allowed('sendDirection')||allowed('resume')||allowed('end')}<div class="controls">{#if allowed('takeFloor')}<button class="sd-button" disabled={busy} on:click={()=>command('take_floor','takeFloor')}>Take the floor</button>{/if}{#if allowed('pause')}<button class="sd-button" disabled={busy} on:click={()=>command('pause','pause')}>Pause bots</button>{/if}{#if allowed('resume')}<button class="sd-button" disabled={busy} on:click={()=>command('resume','resume')}>Resume bots</button>{/if}{#if allowed('end')}<button class="sd-button" disabled={busy} on:click={()=>command('close','end')}>End session</button>{/if}</div>
 {#if allowed('sendDirection')}<form on:submit|preventDefault={()=>command('intervene','sendDirection')}><label>Direction for the bots<textarea bind:value={direction} placeholder="Guide the next step…" rows="2" disabled={busy}/></label><button class="sd-primary" disabled={busy||!direction.trim()}>Send direction</button></form>{/if}<small>Pausing replies does not undo actions already in progress.</small>{:else}<p>Read-only · {person(selected.administratorId)} directs this session.</p>{/if}</div>{/if}
 {#if error}<p role="alert">{error}</p>{/if}
</section>
<style>.work-sessions{min-width:0;display:flex;flex:1;flex-direction:column;min-height:0}header{display:flex;justify-content:space-between;align-items:center;gap:12px}h2{font-size:19px;font-weight:650}header button{flex:none;white-space:nowrap}.session-list{display:flex;gap:8px;overflow:auto;padding:12px 0;border-bottom:1px solid var(--sd-line)}.session-list button{padding:8px 0;min-width:180px;text-align:left}.session-list strong{font-size:14px;font-weight:600}.session-list small{display:block;margin-top:3px}.session-list .selected{color:var(--sd-accent)}small,time,.session-state span{font-size:12px;color:var(--sd-muted)}.transcript{min-height:0;display:flex;flex:1;flex-direction:column;padding-top:12px}.session-state{font-size:13px;font-weight:600}.transcript [role=log]{flex:1;min-height:100px;overflow:auto;margin:10px 0}article{padding:14px 0;border-bottom:1px solid var(--sd-line)}article.human{border-left:3px solid var(--sd-accent);padding-left:12px}.speaker{display:flex;justify-content:space-between;gap:10px;align-items:center}.speaker strong{font-size:13px;font-weight:650}article p{margin-top:6px;font-size:14px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.controls{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--sd-line);padding-top:12px}textarea{width:100%;border:1px solid var(--sd-line);border-radius:9px;background:var(--sd-card);padding:10px;color:inherit;display:block;margin-top:5px}form{display:flex;gap:10px;align-items:flex-end;margin:10px 0}form label{flex:1;font-size:12px}button{min-height:40px}form button{white-space:nowrap;flex:none}@media(max-width:600px){form{flex-wrap:wrap}form label{flex-basis:100%}.transcript [role=log]{min-height:150px}h2{font-size:17px}}</style>
